const canvas = document.querySelector("#canvas");
const ctx = canvas.getContext("2d");

// Set canvas size
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const wavePatterns = [];
const numberOfWaves = 25;

// Initialize waves with random properties
for (let i = 0; i < numberOfWaves; i++) {
  wavePatterns.push({
    baseY: canvas.height / 2 - 100 + Math.random() * 200, // Vertical position of the wave
    wavelength: 0.01 + Math.random() * 0.001, // Controls the wave frequency
    amplitude: 50 + Math.random() * 100, // Height of the wave
    speed: 0.01 + Math.random() * 0.03, // Speed of wave movement
    phase: Math.random() * Math.PI * 2, // Initial phase shift
  });
}

function animateWaves() {
  requestAnimationFrame(animateWaves);

  // Create a fading effect for smooth animation
  ctx.fillStyle = `rgba(0, 0, 0, 0.03)`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw each wave
  wavePatterns.forEach((wave, index) => {
    ctx.beginPath();
    ctx.moveTo(0, wave.baseY);

    for (let x = 0; x < canvas.width; x++) {
      const yOffset =
        Math.sin(x * wave.wavelength + wave.phase) *
        wave.amplitude *
        Math.sin(wave.phase);

      ctx.lineTo(x, wave.baseY + yOffset);
    }

    // Set stroke color with a hue variation for a gradient effect
    ctx.strokeStyle = `hsl(${index / 2 + 170}, 100%, 50%)`;
    ctx.stroke();

    // Update wave phase to create movement
    wave.phase += wave.speed;
  });
}

// Start animation
animateWaves();

// Adjust canvas size on window resize and reposition waves
window.addEventListener("resize", () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  wavePatterns.forEach((wave) => {
    wave.baseY = canvas.height / 2 - 100 + Math.random() * 200;
  });
});
